 assert.deepEqual([...methods].sort(),Object.keys(bodies).sort());for(const method of methods){validate(method,bodies[method]);assert.throws(()=>validate(method,{...bodies[method],extra:true}));for(const invalid of [null,[],undefined,0,'{}',true,()=>{}])assert.throws(()=>validate(method,invalid))};for(const method of [null,{},1,undefined,'signBytes','getMnemonic','__proto__','constructor'])assert.throws(()=>validate(method,{}));const inherited=Object.create({accountId:'a'});inherited.extra='x';assert.throws(()=>validate('balances',inherited));validate('balances',{accountId:'x'.repeat(4096)});for(const accountId of [3,'x'.repeat(4097)])assert.throws(()=>validate('balances',{accountId}));for(const index of [0,999999])validate('addAccount',{index});for(const index of [-1,1000000,.1,NaN,Infinity,'1'])assert.throws(()=>validate('addAccount',{index}));for(const words of [12,24])validate('create',{words});for(const words of [0,15,18,21,'12'])assert.throws(()=>validate('create',{words}));for(const birthday of [0,4294967295])validate('discovery',{accountId:'a',birthday,gap:1,limit:1,blockBudget:0});for(const birthday of [-1,4294967296,.1,'0'])assert.throws(()=>validate('discovery',{accountId:'a',birthday,gap:1,limit:1,blockBudget:0}));for(const gap of [1,100])validate('discovery',{accountId:'a',birthday:0,gap,limit:10000,blockBudget:0});for(const gap of [0,101,.1,'1'])assert.throws(()=>validate('discovery',{accountId:'a',birthday:0,gap,limit:1,blockBudget:0}));for(const limit of [0,10001,.1,'1'])assert.throws(()=>validate('discovery',{accountId:'a',birthday:0,gap:1,limit,blockBudget:0}));assert.throws(()=>validate('associate',{accountId:'a',other:'x'}))
