async function rendererHarness(options={}){
 const html=fs.readFileSync(path.join(root,'ui/index.html'),'utf8');const dom=new JSDOM(html,{url:'wallet://app/',runScripts:'outside-only'});const calls=[];let state={locked:false,walletExists:true,vaultState:'present',...(options.state??{accounts:options.accounts??[{id:'a',network:'testnet',index:0,address:'0x1111111111111111111111111111111111111111'}]})},networks=options.networks??[{id:'testnet',assets:[{id:'testnet:native',symbol:'ETH'}]}],operations=options.operations??[];const handlers={accounts:options.readAccounts??(()=>state),networks:()=>networks,history:()=>operations,prepare:body=>({id:'op-1',accountId:body.accountId,amount:body.amount}),max:()=>({id:'op-max',amount:'123'}),send:()=>({state:'SUBMITTED'}),receive:()=>({png:'AAAA',account:state.accounts[0]}),balances:()=>[{asset:'testnet:native',atomic:'100'}],scanQR:()=> '0x2222222222222222222222222222222222222223',chainHistory:()=>({scope:'last 128 blocks',items:[]}),reconcile:()=>({state:'UNKNOWN'})};
 let lockedListener,unsubscribed=0;dom.window.wallet=Object.fromEntries(methods.map(method=>[method,async(body={})=>{calls.push({method,body:structuredClone(body)});if(handlers[method])return structuredClone(await handlers[method](body));return {}}]));dom.window.wallet.getVersion=()=>options.versionFailure?Promise.reject(Error('public-metadata-unavailable')):Promise.resolve(options.version??'0.1.0-test.17');dom.window.wallet.onLocked=callback=>{lockedListener=callback;return ()=>{lockedListener=undefined;unsubscribed++}};dom.window.fetch=()=>{throw Error('renderer network forbidden')};new vm.Script(fs.readFileSync(path.join(root,'ui/renderer.js'),'utf8'),{filename:path.join(root,'ui/renderer.js')}).runInContext(dom.getInternalVMContext());await tick();await tick();const $=id=>dom.window.document.getElementById(id);return {dom,calls,handlers,$,notifyLock:()=>lockedListener(),unsubscribed:()=>unsubscribed,setState:value=>{state={locked:false,walletExists:true,vaultState:'present',...value}},setNetworks:value=>{networks=value},setOperations:value=>{operations=value},last:()=>calls.at(-1),click:async id=>{$(id).onclick();await tick();await tick()},invoke:async id=>{await $(id).onclick()},close:()=>dom.window.close()};
}

test('TP033 renderer public flows remain inert text, use exact decimal strings and never acquire secrets',async t=>{const h=await rendererHarness();t.after(h.close);assert.equal(h.$('account').options.length,1);assert.equal(h.$('asset').value,'testnet:native');assert.equal(h.$('address').textContent,'0x1111111111111111111111111111111111111111');assert.match(h.$('message').textContent,/Request completed/);assert.equal(h.dom.window.require,undefined);assert.equal(h.dom.window.process,undefined);for(const [id,method,body] of [['unlock','unlock',{}],['create','create',{words:12}],['create24','create',{words:24}],['import','import',{words:12}],['backup','backup',{}],['restore','restore',{}],['password','password',{}]]){const before=h.calls.length;await h.invoke(id);assert.deepEqual(h.calls[before],{method,body})};h.$('index').value='127';let before=h.calls.length;await h.invoke('add');assert.deepEqual(h.calls[before],{method:'addAccount',body:{index:127}});await h.invoke('refresh');assert.deepEqual(h.last(),{method:'balances',body:{accountId:'a'}});assert.match(h.$('balance').textContent,/100/);await h.invoke('receive');assert.equal(h.$('qr').hidden,false);assert.equal(h.$('qr').src,'data:image/png;base64,AAAA');await h.invoke('copy');assert.deepEqual(h.last(),{method:'copyReceive',body:{accountId:'a'}});await h.invoke('saveqr');assert.deepEqual(h.last(),{method:'saveQR',body:{accountId:'a'}});await h.invoke('configure');assert.deepEqual(h.last(),{method:'configure',body:{network:'testnet'}});h.$('recipient').value='a.named.account';before=h.calls.length;await h.invoke('associate');assert.deepEqual(h.calls[before],{method:'associate',body:{accountId:'a',address:'a.named.account'}});await h.invoke('chainhistory');assert.match(h.$('chainhistoryresult').textContent,/last 128 blocks/);h.$('birthday').value='4294967295';h.$('gap').value='100';h.$('limit').value='10000';before=h.calls.length;await h.invoke('discovery');assert.deepEqual(h.calls[before],{method:'discovery',body:{accountId:'a',birthday:4294967295,gap:100,limit:10000,blockBudget:10000}})
});

test('TP042 renderer editing, account selection, QR scan and lock invalidate prepared payments',async t=>{const h=await rendererHarness();t.after(h.close);h.$('recipient').value='public-destination';h.$('amount').value='0.000000000000000001';h.$('memo').value='plain memo';let before=h.calls.length;await h.invoke('prepare');assert.deepEqual(h.calls[before],{method:'prepare',body:{accountId:'a',asset:'testnet:native',recipient:'public-destination',amount:'0.000000000000000001',memo:'plain memo'}});assert.equal(h.$('send').disabled,false);await h.invoke('send');assert.ok(h.calls.some(call=>call.method==='send'&&call.body.id==='op-1'));assert.equal(h.$('send').disabled,true);const sent=h.calls.filter(call=>call.method==='send').length;await h.invoke('send');assert.equal(h.calls.filter(call=>call.method==='send').length,sent);for(const id of ['recipient','amount','memo','asset']){await h.invoke('prepare');h.$(id).dispatchEvent(new h.dom.window.Event('input'));assert.equal(h.$('send').disabled,true);await h.invoke('send');assert.equal(h.calls.filter(call=>call.method==='send').length,sent)}before=h.calls.length;await h.invoke('max');assert.equal(h.calls[before].method,'max');assert.equal(h.calls[before].body.amount,'0');assert.equal(h.$('send').disabled,false);await h.invoke('scan');assert.equal(h.$('recipient').value,'0x2222222222222222222222222222222222222223');assert.equal(h.$('send').disabled,true);await h.invoke('prepare');h.$('account').dispatchEvent(new h.dom.window.Event('change'));assert.equal(h.$('send').disabled,true);await h.invoke('prepare');await h.invoke('lock');assert.deepEqual(h.last(),{method:'lock',body:{}});assert.equal(h.$('send').disabled,true);assert.equal(h.$('account').options.length,0);for(const id of ['diagnostics','preview','balance','chainhistoryresult'])assert.equal(h.$(id).textContent,'Locked');assert.equal(h.$('qr').hidden,true)
});

test('TP060 renderer offers reconciliation only for unresolved original identities and renders hostile metadata as text',async t=>{const dangerous='<img src=x onerror="globalThis.compromised=true">';const states=['UNKNOWN','SUBMITTED','SUBMITTING','SIGNED_NOT_SUBMITTED','REORGED','CONFIRMED','FAILED','CANCELLED'];const h=await rendererHarness({accounts:[{id:'a',network:'testnet',index:0,address:dangerous}],networks:[{id:'testnet',assets:[{id:'testnet:native',symbol:dangerous}]}],operations:states.map((state,index)=>({state,plan:{id:'op-'+index},detail:dangerous}))});t.after(h.close);assert.equal(h.$('address').textContent,dangerous);assert.equal(h.$('address').children.length,0);assert.equal(h.$('operations').querySelectorAll('img,script').length,0);assert.equal(h.dom.window.compromised,undefined);const buttons=h.$('operations').querySelectorAll('button');assert.equal(buttons.length,5);let before=h.calls.length;await buttons[0].onclick();assert.deepEqual(h.calls[before],{method:'reconcile',body:{id:'op-0'}});assert.match(h.$('preview').textContent,/UNKNOWN/);assert.ok(!h.calls.some(call=>call.method==='retry'||call.method==='send'));h.setOperations(null);await h.invoke('history');assert.equal(h.$('operations').children.length,0);h.setState({});await h.invoke('unlock');assert.equal(h.$('account').options.length,0);assert.equal(h.$('address').textContent,'Locked or no account');h.setState({accounts:[{id:'b',network:'missing',index:127,address:'public'}]});h.setNetworks([]);await h.invoke('unlock');assert.equal(h.$('asset').options.length,0);assert.equal(h.$('address').textContent,'public');h.handlers.receive=()=>({png:'BBBB'});await h.invoke('receive');assert.equal(h.$('qr').src,'data:image/png;base64,BBBB')
});

