test('TP043 main polls only idle status, never sends polling activity, and clears the renderer immediately on every lock',async t=>{
 const h=mainHarness();t.after(h.cleanup);await h.ready();assert.equal(h.intervals.size,1);const interval=h.intervals.values().next().value;assert.equal(interval.ms,5000);
 for(const body of [null,0,false,[],{}, {locked:false},{locked:'true'}]){const before=h.outbound.length;interval.fn();assert.equal(h.outbound.at(-1).method,'status');interval.fn();assert.equal(h.outbound.length,before+1);h.reply(h.outbound.at(-1),body);await tick();assert.equal(h.notifications.length,0)}
 interval.fn();h.reply(h.outbound.at(-1),{locked:true});await tick();assert.deepEqual(h.notifications,[['wallet:locked']]);
 const user=h.call('accounts');const before=h.outbound.length;interval.fn();assert.equal(h.outbound.length,before);h.reply(h.outbound.at(-1),{accounts:[]});await user;
 const status=h.call('status');h.reply(h.outbound.at(-1),{locked:true});await status;assert.equal(h.notifications.length,2);
 const unlockedStatus=h.call('status');h.reply(h.outbound.at(-1),{locked:false});await unlockedStatus;assert.equal(h.notifications.length,2);
 const manual=h.call('lock');assert.equal(h.notifications.length,3);h.reply(h.outbound.at(-1),{locked:true});await manual;
 for(const event of ['lock-screen','suspend','shutdown']){const notices=h.notifications.length;h.powerMonitor.emit(event);assert.equal(h.notifications.length,notices+1);assert.equal(h.outbound.at(-1).method,'lock');h.reply(h.outbound.at(-1),{})}
 h.windows[0].webContents.destroyed=true;const requests=h.outbound.length,notices=h.notifications.length;interval.fn();assert.equal(h.outbound.length,requests);h.powerMonitor.emit('lock-screen');h.reply(h.outbound.at(-1),{});assert.equal(h.notifications.length,notices);h.windows[0].webContents.destroyed=false;
 h.windows[0].emit('closed');assert.equal(h.intervals.size,0);interval.fn();assert.equal(h.stdin.destroyed,true);h.ipcMain.emit('wallet:activity',{sender:undefined,senderFrame:null});await assert.rejects(h.call('status'),/Untrusted frame/);assert.ok(h.outbound.every(value=>value.method!=='activity'));
});

test('TP043 status-poll failure ends the session and clears cached public data',async t=>{const h=mainHarness();t.after(h.cleanup);await h.ready();h.intervals.values().next().value.fn();h.reply(h.outbound.at(-1),null,{error:'PRIVATE-error-is-not-forwarded'});await tick();await tick();assert.equal(h.intervals.size,0);assert.equal(h.stdin.destroyed,true);assert.deepEqual(h.notifications,[['wallet:locked']])});

test('TP041 account hiding and manual recovery ranges have exact bounded public schemas',()=>{
 for(const hidden of [true,false])validate('hideAccount',{accountId:'a',hidden});for(const hidden of [null,0,1,'true',{},undefined])assert.throws(()=>validate('hideAccount',{accountId:'a',hidden}));
 for(const [start,end] of [[0,0],[0,19],[999999,999999]])validate('discoverAccounts',{start,end});for(const [start,end] of [[-1,0],[0,1000000],[.5,1],[1,'2']])assert.throws(()=>validate('discoverAccounts',{start,end}));
 for(const blockBudget of [0,1,2000000])validate('discovery',{accountId:'a',birthday:0,gap:1,limit:1,blockBudget});for(const blockBudget of [-1,2000001,.5,'0',NaN,Infinity])assert.throws(()=>validate('discovery',{accountId:'a',birthday:0,gap:1,limit:1,blockBudget}));
});

function assertRendererLocked(h){assert.equal(h.$('account').options.length,0);assert.equal(h.$('asset').options.length,0);assert.equal(h.$('operations').children.length,0);assert.equal(h.$('qr').hidden,true);assert.equal(h.$('qr').getAttribute('src'),null);assert.equal(h.$('send').disabled,true);for(const id of ['recipient','amount','memo'])assert.equal(h.$(id).value,'');for(const id of ['address','diagnostics','preview','balance','chainhistoryresult'])assert.equal(h.$(id).textContent,'Locked');assert.match(h.$('message').textContent,/Wallet locked/)}
function deferred(){let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b});return {promise,resolve,reject}}

test('TP043 automatic lock removes cached accounts, QR data, diagnostics, history and the pending plan',async t=>{
 const h=await rendererHarness({operations:[{state:'UNKNOWN',plan:{id:'public-original'}}]});t.after(h.close);await h.invoke('receive');await h.invoke('refresh');await h.invoke('chainhistory');h.$('recipient').value='public-recipient';h.$('amount').value='123';h.$('memo').value='public-memo';await h.invoke('prepare');const before=h.calls.length;h.notifyLock();assertRendererLocked(h);assert.equal(h.calls.length,before);await h.invoke('send');assert.ok(!h.calls.some(call=>call.method==='send'));h.dom.window.dispatchEvent(new h.dom.window.Event('beforeunload'));assert.equal(h.unsubscribed(),1)
});

test('TP043 delayed public replies after a lock cannot repopulate the renderer or authorize a stale send',async t=>{
 for(const [button,method,value] of [['refresh','balances',[{atomic:'stale'}]],['receive','receive',{png:'STALE',account:{id:'a',address:'stale-address'}}],['chainhistory','chainHistory',{entries:['stale']}],['prepare','prepare',{id:'stale-plan'}],['max','max',{id:'stale-max'}],['scan','scanQR','stale-recipient'],['history','history',[{state:'UNKNOWN',plan:{id:'stale-operation'}}]]]){
  const h=await rendererHarness();t.after(h.close);const pending=deferred();h.handlers[method]=()=>pending.promise;const run=h.invoke(button);await tick();h.notifyLock();pending.resolve(value);await run;assertRendererLocked(h);await h.invoke('send');assert.ok(!h.calls.some(call=>call.method==='send'));
 }
 for(const delayed of ['accounts','networks']){const h=await rendererHarness();t.after(h.close);const pending=deferred();h.handlers[delayed]=()=>pending.promise;const run=h.invoke('unlock');await tick();h.notifyLock();pending.resolve(delayed==='accounts'?{accounts:[{id:'stale',address:'stale-public-address'}]}:[{id:'stale',assets:[]}]);await run;assertRendererLocked(h)}
 const h=await rendererHarness();t.after(h.close);const pending=deferred();h.handlers.balances=()=>pending.promise;const run=h.invoke('refresh');await tick();h.notifyLock();pending.reject(Error('private-untrusted-detail'));await run;assertRendererLocked(h);assert.ok(!h.dom.window.document.body.textContent.includes('private-untrusted-detail'));
});

