test('TP042 only durable unsigned PREPARED operations offer explicit cancellation of their original ID',async t=>{
 const states=['PREPARED','AWAITING_CONFIRMATION','SIGNED_NOT_SUBMITTED','SUBMITTING','UNKNOWN','SUBMITTED','CONFIRMED','FAILED','CANCELLED'];const operations=states.map((state,index)=>({state,plan:{id:'public-op-'+index}}));const h=await rendererHarness({operations});t.after(h.close);await h.invoke('prepare');const buttons=[...h.$('operations').querySelectorAll('button')],cancel=buttons.filter(button=>button.textContent==='Cancel unsigned preparation');assert.equal(cancel.length,1);h.handlers.cancelPrepared=body=>{assert.equal(body.id,'public-op-0');h.setOperations(operations.map(operation=>operation.plan.id===body.id?{...operation,state:'CANCELLED'}:operation))};const before=h.calls.length;await cancel[0].onclick();assert.deepEqual(h.calls[before],{method:'cancelPrepared',body:{id:'public-op-0'}});assert.equal(h.$('send').disabled,true);assert.equal(h.$('preview').textContent,'Unsigned preparation cancelled.');assert.equal([...h.$('operations').querySelectorAll('button')].filter(button=>button.textContent==='Cancel unsigned preparation').length,0);assert.ok(!h.calls.some(call=>call.method==='send'));
 validate('cancelPrepared',{id:'public-op-0'});for(const body of [{id:1},{id:'op',state:'PREPARED'},{id:'op',password:'forbidden'}])assert.throws(()=>validate('cancelPrepared',body));
});

