test('TP041 visible app version is read-only local metadata with exact sender, frame and origin checks',async t=>{
 const h=mainHarness({version:'0.2.13'});t.after(h.cleanup);await h.ready();assert.equal(await h.version(),'0.2.13');assert.equal(h.outbound.length,0);const good=h.event();for(const bad of [{sender:{},senderFrame:good.senderFrame},{sender:good.sender,senderFrame:{url:'wallet://app/'}},{sender:good.sender,senderFrame:null}])await assert.rejects(h.version(bad),/Untrusted frame/);for(const url of ['https://evil.test/','wallet://app.evil/','file:///tmp/app']){good.senderFrame.url=url;await assert.rejects(h.version(good),/Untrusted frame/)}good.senderFrame.url='wallet://app/';h.windows[0].emit('closed');await assert.rejects(h.version(good),/Untrusted frame/);
 const r=await rendererHarness({version:'0.2.13+public-test'});t.after(r.close);assert.equal(r.$('version').textContent,'Version 0.2.13+public-test');r.notifyLock();assert.equal(r.$('version').textContent,'Version 0.2.13+public-test');const failed=await rendererHarness({versionFailure:true});t.after(failed.close);assert.equal(failed.$('version').textContent,'Version unavailable');const hostile=await rendererHarness({version:'<img src=x onerror=alert(1)>'});t.after(hostile.close);assert.equal(hostile.$('version').children.length,0)
});

test('TP043 native prompt activity renews only its correlated six-minute deadline and never resolves or creates a request',async t=>{
 const bodies={create:{words:12},import:{words:12},unlock:{},backup:{},restore:{},password:{},receive:{accountId:'a'},copyReceive:{accountId:'a'},saveQR:{accountId:'a'},scanQR:{},configure:{network:'n'},associate:{accountId:'a',address:'named'},discovery:{accountId:'a',birthday:0,gap:1,limit:1,blockBudget:0},discoverAccounts:{start:0,end:1},send:{id:'original'}};
 for(const [method,body] of Object.entries(bodies)){const h=mainHarness();t.after(h.cleanup);await h.ready();let settled=false;const p=h.call(method,body).then(value=>{settled=true;return value});const request=h.outbound[0],initial=[...h.timers.values()][0];assert.equal(initial.ms,360000);h.reply(request,{}, {method:'activity'});assert.equal(h.timers.size,1);const renewed=[...h.timers.values()][0];assert.notEqual(renewed,initial);assert.equal(renewed.ms,360000);initial.fn();await tick();assert.equal(settled,false);assert.equal(h.stdin.destroyed,false);h.reply(request,{}, {method:'activity'});h.clock(11_001);h.reply(request,{}, {method:'activity'});h.intervals.values().next().value.fn();await tick();assert.equal(settled,false);assert.equal(h.outbound.length,1);assert.equal(h.notifications.length,0);h.reply(request,{publicResult:true});assert.deepEqual(plain(await p),{publicResult:true});assert.equal(h.timers.size,0);renewed.fn();await tick();assert.equal(h.stdin.destroyed,false)}
});

test('TP043 malformed, non-native, stale and excessive native activity fail closed without exposing input values',async t=>{
 const mutations=[r=>({...r,body:null}),r=>({...r,body:[]}),r=>({...r,body:'input must not exist'}),r=>({...r,body:1}),r=>({...r,body:{key:'CANARY-native-input'}}),r=>({...r,error:''}),r=>({...r,error:'CANARY-native-error'}),r=>({...r,id:'stale-id'}),r=>({...r,session:'b'.repeat(32)}),r=>({...r,version:2})];
 for(const mutation of mutations){const h=mainHarness();t.after(h.cleanup);await h.ready();const promise=h.call('unlock');const rejected=assert.rejects(promise,/Wallet session ended/);h.stdout.write(framed(mutation({...h.outbound[0],method:'activity',body:{}})));await rejected;assert.equal(h.timers.size,0);assert.equal(h.stdin.destroyed,true);assert.ok(h.notifications.every(args=>JSON.stringify(args)==='["wallet:locked"]'))}
 {const h=mainHarness();t.after(h.cleanup);await h.ready();const promise=h.call('status');const rejected=assert.rejects(promise,/Wallet session ended/);h.reply(h.outbound[0],{}, {method:'activity'});await rejected}
 {const h=mainHarness();t.after(h.cleanup);await h.ready();const original=h.call('unlock'),request=h.outbound[0];h.reply(request,{});await original;const next=h.call('unlock');const rejected=assert.rejects(next,/Wallet session ended/);h.reply(request,{}, {method:'activity'});await rejected}
 {const h=mainHarness();t.after(h.cleanup);await h.ready();const promise=h.call('unlock');const rejected=assert.rejects(promise,/Wallet session ended/);for(let i=0;i<65;i++)h.reply(h.outbound[0],{}, {method:'activity'});await rejected;assert.equal(h.outbound.length,1);assert.equal(h.timers.size,0)}
});

test('TP031 first launch explicitly creates one shared-root wallet in the native signer and lists every returned network under Main account',async t=>{
 const h=await rendererHarness({state:{locked:true,walletExists:false,vaultState:'missing',accounts:[]}});t.after(h.close);
 assert.deepEqual(h.calls,[{method:'accounts',body:{}}]);assert.equal(h.$('onboarding').hidden,false);assert.match(h.$('onboardtitle').textContent,/Create your app password/);assert.equal(h.$('onboardcreate').hidden,false);assert.equal(h.$('onboardunlock').hidden,true);assert.equal(h.$('walletcontent').hidden,true);assert.equal(h.$('accountgroups').children.length,0);assert.match(h.$('onboarddescription').textContent,/one BIP39 root/);assert.match(h.dom.window.document.querySelector('.recovery-note').textContent,/both are required for recovery/);assert.equal(h.dom.window.document.querySelectorAll('input[type=password],textarea,[name=mnemonic],[name=password]').length,0);
 const fixture=JSON.parse(fs.readFileSync(path.join(__dirname,'fixtures/networks-testnet.json'),'utf8'));
 for(const [name,expected] of Object.entries(fixture.sourceSHA256))assert.equal(crypto.createHash('sha256').update(fs.readFileSync(path.join(root,'..',name))).digest('hex'),expected,'Registry changed; regenerate and review the public DTO fixture: '+name);
 const networks=fixture.networks,ids=networks.map(network=>network.id);assert.equal(ids.length,12);assert.equal(networks.flatMap(network=>network.assets).length,14);
 const accounts=ids.map((network,i)=>({id:'public-'+i,index:0,network,address:'public-address-'+i}));
 const native=deferred();h.handlers.create=()=>native.promise;
 const first=h.invoke('onboardcreate');await tick();assert.equal(h.$('onboardcreate').disabled,true);await h.invoke('onboardcreate');await h.invoke('create24');assert.equal(h.calls.filter(call=>call.method==='create').length,1);assert.deepEqual(h.last(),{method:'create',body:{words:12}});
 h.setState({accounts,backupVerified:false,environment:'testnet'});h.setNetworks(networks);native.resolve({});await first;
 assert.equal(h.$('onboardcreate').disabled,false);assert.equal(h.$('onboarding').hidden,true);assert.equal(h.$('walletcontent').hidden,false);assert.equal(h.$('emptyactions').hidden,true);assert.equal(h.$('accountgroups').children.length,1);assert.equal(h.$('accountgroups').querySelector('h2').textContent,'Main account');assert.match(h.$('accountgroups').textContent,/Derivation index 0/);assert.equal(h.$('accountgroups').querySelectorAll('.walletcard').length,ids.length);assert.deepEqual([...h.$('accountgroups').querySelectorAll('h3')].map(node=>node.textContent),networks.map(network=>network.name));assert.equal(h.$('account').options.length,ids.length);assert.equal(h.calls.filter(call=>call.method==='create').length,1);assert.ok(!h.calls.some(call=>call.method==='addAccount'||call.method==='send'||call.method==='balances'));
 const cards=h.$('accountgroups').querySelectorAll('.walletcard');assert.deepEqual([...cards].map(card=>card.querySelector('p').textContent),networks.map(network=>network.assets.map(asset=>asset.symbol).join(' · ')));cards[5].querySelector('button').click();assert.equal(h.$('account').value,'public-5');assert.equal(h.$('address').textContent,'public-address-5');assert.equal(h.dom.window.document.activeElement,h.$('account'));assert.equal(h.$('send').disabled,true);assert.equal(h.$('profile').textContent,'Testnet profile');
 assert.equal(h.$('backupcallout').hidden,false);assert.match(h.$('backupstatus').textContent,/verification required/);h.handlers.backup=()=>{h.setState({accounts,backupVerified:true});return {}};const before=h.calls.length;await h.invoke('backupnow');assert.deepEqual(h.calls[before],{method:'backup',body:{}});assert.equal(h.$('backupcallout').hidden,true);assert.equal(h.$('backupstatus').textContent,'Encrypted backup verified');
 h.notifyLock();assert.equal(h.$('accountgroups').children.length,0);assert.equal(h.$('walletcontent').hidden,true);assert.equal(h.$('backupcallout').hidden,true);assert.equal(h.$('onboardunlock').hidden,false);assert.equal(h.$('onboardcreate').hidden,true);
});

test('TP031 profile is explicit before onboarding and follows trusted snapshot metadata without rendering arbitrary environment text',async t=>{
 const h=await rendererHarness({state:{locked:true,walletExists:false,vaultState:'missing',environment:''}});t.after(h.close);assert.equal(h.$('profile').textContent,'Testnet profile');
 h.setState({locked:true,environment:'mainnet'});await h.invoke('onboardretry');assert.equal(h.$('profile').textContent,'Mainnet profile');assert.equal(h.$('profile').dataset.environment,'mainnet');h.notifyLock();assert.equal(h.$('profile').textContent,'Mainnet profile');
 h.setState({locked:true,environment:'<img src=x onerror=alert(1)>'});await h.invoke('onboardretry');assert.equal(h.$('profile').children.length,0);assert.equal(h.$('profile').textContent,'Mainnet profile');
});

test('TP031 existing locked vault offers unlock rather than new-wallet creation and reveals no cached account cards',async t=>{
 const h=await rendererHarness({state:{locked:true,walletExists:true,vaultState:'present',accounts:[{id:'stale',address:'PUBLIC-stale-must-not-show'}]}});t.after(h.close);assert.deepEqual(h.calls,[{method:'accounts',body:{}}]);assert.equal(h.$('onboardtitle').textContent,'Welcome back');assert.equal(h.$('onboardunlock').hidden,false);assert.equal(h.$('onboardcreate').hidden,true);assert.equal(h.$('emptyactions').hidden,true);assert.equal(h.$('accountgroups').textContent,'');assert.ok(!h.dom.window.document.body.textContent.includes('PUBLIC-stale-must-not-show'));
 h.handlers.unlock=()=>{h.setState({accounts:[{id:'fresh',network:'testnet',index:0,address:'fresh-public-address'}]});return {}};const before=h.calls.length;await h.invoke('onboardunlock');assert.deepEqual(h.calls[before],{method:'unlock',body:{}});assert.equal(h.$('onboarding').hidden,true);assert.equal(h.$('address').textContent,'fresh-public-address');assert.ok(!h.calls.some(call=>call.method==='create'));
});

test('TP031 unavailable or inconsistent storage never authorizes onboarding creation or restoration; retry requires confirmed absence',async t=>{
 for(const state of [{walletExists:true,vaultState:'unavailable'},{walletExists:false,vaultState:'unavailable'},{walletExists:true,vaultState:'missing'},{walletExists:false,vaultState:'present'},{walletExists:undefined,vaultState:undefined},{walletExists:false,vaultState:'missing',locked:false}]){
  const h=await rendererHarness({state:{locked:true,...state}});t.after(h.close);
  if(state.vaultState==='missing'&&state.walletExists===false){assert.equal(h.$('onboardcreate').hidden,false);assert.equal(h.$('walletcontent').hidden,true);continue}
  assert.equal(h.$('onboardtitle').textContent,'Wallet storage unavailable');assert.equal(h.$('onboardcreate').hidden,true);assert.equal(h.$('emptyactions').hidden,true);assert.equal(h.$('onboardunlock').hidden,true);assert.equal(h.$('onboardretry').hidden,false);assert.deepEqual(h.calls,[{method:'accounts',body:{}}]);
  h.setState({locked:true,walletExists:false,vaultState:'missing',accounts:[]});await h.invoke('onboardretry');assert.equal(h.$('onboardcreate').hidden,false);assert.equal(h.$('onboardretry').hidden,true);assert.equal(h.calls.filter(call=>call.method==='create'||call.method==='restore').length,0);
 }
});

test('TP031 initial status failure is unavailable, native cancellation preserves setup, and release status opens specific honest evidence limits',async t=>{
 const h=await rendererHarness({readAccounts:()=>{throw Error('CANARY-private-storage-error')}});t.after(h.close);assert.equal(h.$('onboardtitle').textContent,'Wallet storage unavailable');assert.equal(h.$('onboardcreate').hidden,true);assert.ok(!h.dom.window.document.body.textContent.includes('CANARY-private-storage-error'));
 h.handlers.accounts=()=>({locked:true,walletExists:false,vaultState:'missing',accounts:[]});await h.invoke('onboardretry');h.handlers.create=()=>{throw Error('CANARY-native-password-cancel')};await h.invoke('onboardcreate');assert.equal(h.$('onboardcreate').disabled,false);assert.equal(h.$('onboardcreate').hidden,false);assert.match(h.$('message').textContent,/failed, unavailable or cancelled/);assert.ok(!h.dom.window.document.body.textContent.includes('CANARY-native-password-cancel'));assert.equal(h.$('accountgroups').children.length,0);
 const link=h.$('release-link');assert.match(link.textContent,/development; verification outstanding/);assert.equal(h.$('release-status').open,false);link.click();assert.equal(h.$('release-status').open,true);assert.equal(h.dom.window.location.hash,'');assert.match(h.$('release-status').textContent,/Public funded testnet roundtrips/);assert.match(h.$('release-status').textContent,/24-hour soak and independent security review remain outstanding/);assert.equal(h.dom.window.document.querySelector('.notice'),null);
});
